"""Golden case tests for council-tax-single-person-discount - generated by Skill Forge."""

from decimal import Decimal

from tempo_core.models import Fact, NotEligible, ProofTrace
from tempo_core.rules.engine import evaluate_delay_repay


def test_eligible_delay_repay_15_min():
    pack = load_rule_pack("council-tax-single-person-discount")
    facts = (Fact(key="delay", value=15, source="test", confidence=1.0),)
    result = evaluate_delay_repay(
        pack, delay_minutes=15, fare_gbp=Decimal("20.00"), facts=facts, trace_id="test"
    )
    assert isinstance(result, ProofTrace)
    assert result.amount_gbp == Decimal("5.00")  # 25% of 20


def test_not_eligible_below_threshold():
    pack = load_rule_pack("council-tax-single-person-discount")
    facts = (Fact(key="delay", value=10, source="test", confidence=1.0),)
    result = evaluate_delay_repay(
        pack, delay_minutes=10, fare_gbp=Decimal("20.00"), facts=facts, trace_id="test"
    )
    assert isinstance(result, NotEligible)
